using Microsoft.Xna.Framework;
using Microsoft.Xna.Framework.Graphics;
using Microsoft.Xna.Framework.Input;
using static StarlightSyndicateDemo.HudCanvas;
namespace StarlightSyndicateDemo;
public sealed partial class DemoGame
{
 readonly Dictionary<string,RenderTarget2D> informationPreviews=[];readonly Dictionary<string,Rectangle> informationPreviewRects=[];DesktopWindow? informationPreviewDrag;Vector2 informationPreviewLast;
 void PrepareInformationPreviews(){var live=desktop.Where(w=>w.Kind==ViewMode.Information).TakeLast(8).Select(w=>w.InstanceId).ToHashSet();foreach(var id in informationPreviews.Keys.Where(k=>!live.Contains(k)).ToArray()){informationPreviews[id].Dispose();informationPreviews.Remove(id);}foreach(var w in desktop.Where(w=>w.Kind==ViewMode.Information&&!w.Minimized&&w.InfoTab=="Model")){var e=ResolveInformation(w.InfoKey);if(e?.Kind!="Ship"||!live.Contains(w.InstanceId))continue;string id=e.Id=="player"?world.Player.CombatHull:e.Id;if(!renderer.HasPreview(id))continue;if(!informationPreviews.TryGetValue(w.InstanceId,out var target)){target=new RenderTarget2D(GraphicsDevice,400,420,false,SurfaceFormat.Color,DepthFormat.Depth24);informationPreviews[w.InstanceId]=target;}int oldLod=renderer.PreviewLod;GraphicsDevice.SetRenderTarget(target);GraphicsDevice.Clear(new Color(7,14,22));renderer.PreviewLod=w.InfoModelLod;renderer.DrawPreview(id,w.InfoModelYaw,w.InfoModelPitch,w.InfoModelZoom,id==world.Player.CombatHull?world.Player:null);renderer.PreviewLod=oldLod;}}
 void DrawInformationModel(DesktopWindow w,InformationEntry e,Rectangle body){int x=body.X,y=body.Y;int bw=Math.Max(50,(body.Width-18)/6);ui.Button(new(x,y,bw,25),"Left",()=>w.InfoModelYaw-=.2f,"Info model rotate left");ui.Button(new(x+bw+3,y,bw,25),"Right",()=>w.InfoModelYaw+=.2f,"Info model rotate right");ui.Button(new(x+2*(bw+3),y,bw,25),"+",()=>w.InfoModelZoom=Math.Max(.6f,w.InfoModelZoom-.1f),"Info model zoom in");ui.Button(new(x+3*(bw+3),y,bw,25),"-",()=>w.InfoModelZoom=Math.Min(2,w.InfoModelZoom+.1f),"Info model zoom out");ui.Button(new(x+4*(bw+3),y,bw,25),"LOD "+w.InfoModelLod,()=>w.InfoModelLod=(w.InfoModelLod+1)%3,"Info model LOD");ui.Button(new(x+5*(bw+3),y,bw,25),"Reset",()=>{w.InfoModelYaw=.7f;w.InfoModelPitch=-.25f;w.InfoModelZoom=1;},"Info model reset");int h=Math.Max(1,body.Height-58),width=Math.Min(body.Width,(int)(h*400f/420));var viewport=new Rectangle(body.X+(body.Width-width)/2,body.Y+31,width,h);informationPreviewRects[w.Owner]=viewport;if(informationPreviews.TryGetValue(w.InstanceId,out var preview))ui.Image(preview,viewport);else ui.Text("Original model is not yet integrated for this hull.",x,y+55,Muted,11);ui.Text("Drag to rotate / wheel to zoom / independent preview camera",x,body.Bottom-18,Cyan,10);}
 bool InformationPreviewInput(MouseState m){if(informationPreviewDrag!=null){if(m.LeftButton==ButtonState.Pressed){var delta=mouse-informationPreviewLast;informationPreviewDrag.InfoModelYaw+=delta.X*.01f;informationPreviewDrag.InfoModelPitch=Math.Clamp(informationPreviewDrag.InfoModelPitch+delta.Y*.01f,-1.3f,1.3f);informationPreviewLast=mouse;}else informationPreviewDrag=null;return true;}var w=WindowAt(mouse);if(w?.Kind!=ViewMode.Information||w.Minimized||w.InfoTab!="Model"||!informationPreviewRects.TryGetValue(w.Owner,out var rect)||!rect.Contains(mouse.ToPoint()))return false;int wheel=m.ScrollWheelValue-oldMouse.ScrollWheelValue;if(wheel!=0){w.InfoModelZoom=Math.Clamp(w.InfoModelZoom-wheel/120*.1f,.6f,2);return true;}if(m.LeftButton==ButtonState.Pressed&&oldMouse.LeftButton==ButtonState.Released){informationPreviewDrag=w;informationPreviewLast=mouse;desktop.Remove(w);desktop.Add(w);}return true;}
}
